import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);
    // State mới: Lưu phòng đang được chọn để xem lịch sử
    const [viewRoom, setViewRoom] = useState(null);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // Logic: Nếu là tháng cũ -> Toàn bộ đã thanh toán (màu trắng)
    // Nếu là tháng hiện tại hoặc tương lai -> Màu vàng
    const isPastMonth = selectedYear < currentYear || (selectedYear === currentYear && selectedMonth < currentMonth);
    const totalReceived = isPastMonth ? (5000000 * 45) : 0;

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: '100%'
        }} className="glass-card">

            {/* Header */}
            <div style={{ padding: '20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(parseInt(e.target.value))} style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select value={selectedYear} onChange={(e) => setSelectedYear(parseInt(e.target.value))} style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI - CLICK VÀO ĐỂ XEM CHI TIẾT */}
                <div style={{ 
                    width: '210px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '12px', backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '20px', border: '1px solid rgba(255,255,255,0.1)'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setViewRoom(room)} // Lưu phòng được click
                            style={{ 
                                background: isPastMonth ? 'rgba(255,255,255,0.9)' : '#ffcc00', 
                                color: '#333', 
                                padding: '8px 0', 
                                borderRadius: '8px', 
                                textAlign: 'center', 
                                fontSize: '11px', 
                                fontWeight: 'bold', 
                                cursor: 'pointer',
                                border: viewRoom === room ? '2px solid #8b5e5e' : '1px solid rgba(0,0,0,0.05)',
                                transform: viewRoom === room ? 'scale(1.05)' : 'none',
                                transition: '0.2s'
                            }}>
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI - KHUNG TRẮNG CỐ ĐỊNH */}
                <div style={{ 
                    flex: 1, backgroundColor: '#ffffff', borderRadius: '25px', 
                    padding: '30px', display: 'flex', flexDirection: 'column',
                    color: '#000', boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)',
                    overflow: 'hidden'
                }}>

                    <div style={{ 
                        marginBottom: '20px', padding: '20px', backgroundColor: '#f8f9fa', 
                        borderRadius: '15px', borderLeft: '8px solid #8b5e5e', flexShrink: 0 
                    }}>
                        <div style={{ fontSize: '18px', fontWeight: 'bold', color: '#555' }}>Tổng tiền nhận được (T{selectedMonth}/{selectedYear}):</div>
                        <div style={{ fontSize: '40px', fontWeight: '800', color: totalReceived > 0 ? '#28a745' : '#999' }}>
                            {totalReceived.toLocaleString()}đ
                        </div>
                    </div>

                    <h3 style={{ borderBottom: '2px solid #eee', paddingBottom: '10px', marginBottom: '10px', flexShrink: 0 }}>
                        {viewRoom ? `Lịch sử phòng: ${viewRoom}` : 'Chọn phòng để xem lịch sử'}
                    </h3>

                    <div style={{ flex: 1, overflowY: 'auto', minHeight: 0 }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                            <thead style={{ position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 1 }}>
                                <tr style={{ textAlign: 'left', color: '#888', fontSize: '14px' }}>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Phòng</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Số tiền</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Nội dung</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Thời gian & Giờ</th>
                                </tr>
                            </thead>
                            <tbody>
                                {viewRoom ? (
                                    isPastMonth ? (
                                        <tr style={{ borderBottom: '1px solid #f9f9f9' }}>
                                            <td style={{ padding: '12px', fontWeight: 'bold' }}>{viewRoom}</td>
                                            <td style={{ padding: '12px', color: '#28a745', fontWeight: '600' }}>5.000.000đ</td>
                                            <td style={{ padding: '12px', fontSize: '14px' }}>Tiền phòng T{selectedMonth}</td>
                                            <td style={{ padding: '12px', fontSize: '12px', color: '#999' }}>
                                                01/{selectedMonth.toString().padStart(2, '0')}/{selectedYear} <br/> 
                                                <span style={{color: '#8b5e5e'}}>08:30:15</span>
                                            </td>
                                        </tr>
                                    ) : (
                                        <tr>
                                            <td colSpan="4" style={{ textAlign: 'center', padding: '100px 0', color: '#ff4d4d', fontWeight: 'bold', fontSize: '18px' }}>
                                                CHƯA THANH TOÁN
                                            </td>
                                        </tr>
                                    )
                                ) : (
                                    <tr>
                                        <td colSpan="4" style={{ textAlign: 'center', padding: '100px 0', color: '#ccc', fontStyle: 'italic', fontSize: '16px' }}>
                                            Vui lòng nhấn vào một số phòng ở bên trái...
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
